public class Main {
    public static void main(String[] args) {
        Integer[] nilai = {70, 85, 60};
        Double[] berat = {1.5, 2.25};
        String[] buah = {"mangga", "apel", "jeruk"};

        System.out.println(total(nilai));
        System.out.println(total(berat));
        System.out.println(terbesar(nilai));
        System.out.println(terbesar(buah));
    }

    static <T extends Number> double total(T[] data) {
        double hasil = 0;
        for (T x : data) {
            hasil += x.doubleValue();
        }
        return hasil;
    }

    static <T extends Comparable<T>> T terbesar(T[] data) {
        T juara = data[0];
        for (T x : data) {
            if (x.compareTo(juara) > 0) {
                juara = x;
            }
        }
        return juara;
    }
}

