public class Main {
    public static void main(String[] args) {
        Integer[] d = {2, 4, 9};
        System.out.println(rata(d));
    }

    static <T extends Number> double rata(T[] data) {
        double total = 0;
        for (T x : data) {
            total += x.doubleValue();
        }
        return total / data.length;
    }
}

