public class Main {
    public static void main(String[] args) {
        Integer[] angka = {7, 2, 9};
        String[] buah = {"jeruk", "apel", "mangga"};
        System.out.println(terkecil(angka));
        System.out.println(terkecil(buah));
    }

    static <T extends Comparable<T>> T terkecil(T[] data) {
        T hasil = data[0];
        for (T x : data) {
            if (x.compareTo(hasil) < 0) {
                hasil = x;
            }
        }
        return hasil;
    }
}

